-- evt:refill
RegisterEvent(14, nil, function()
    if not (IsQBitSet(QBit(113143)) and not (IsAtLeast(MapVar(7), 1))) then
        SetValue(MapVar(7), 1)
        return
    end
    SetValue(MapVar(1), 0)
    SetValue(MapVar(2), 0)
    SetValue(MapVar(3), 0)
    SetValue(MapVar(4), 0)
    SetValue(MapVar(5), 0)
    ClearQBit(QBit(113143))
    evt.StatusText("The veins glitter again: the God of Minerals has been at work.", 6)
    SetValue(MapVar(7), 1)
end, nil)

